def second_largest(nums):
    first = second = float("-inf")
    for n in nums:
        if n > first:
            second = first
            first = n
        elif n > second:
            second = n
    return second

scores = [4, 8, 8, 2]
show(scores, "scores")
print(second_largest(scores))

