def is_palindrome(text):
    """Same forwards and backwards, ignoring punctuation and case."""
    cleaned = ""
    for ch in text:
        if ch.isalnum():
            cleaned += ch
    return cleaned == cleaned[::-1]

phrase = "A man, a plan, a canal: Panama"
print(is_palindrome(phrase))
print(is_palindrome("racecar"))

