def longest_run(items):
    if not items:
        return 0
    best = 1
    current = 1
    for i in range(1, len(items)):
        if items[i] == items[i - 1]:
            current += 1
        else:
            best = max(best, current)
            current = 1
    return best

print(longest_run([1, 1, 2, 2, 2, 3]))

