def depth(x):
    # A plain value has no list around it
    if not isinstance(x, list):
        return 0
    # Ask every item how deep it goes
    depths = [depth(item) for item in x]
    # This list adds one level on top of its deepest item
    return 1 + max(depths)

data = [1, [2, [3]], 4]
print(depth(data))

