def group_by_grade(scores):
    """Return {grade: [names]} for everyone with that grade."""
    groups = dict.fromkeys(scores.values(), [])
    for name, grade in scores.items():
        groups[grade].append(name)
    return groups


roster = {"Ana": "A", "Bo": "B", "Cy": "A"}
result = group_by_grade(roster)
print(result)
show(result, "names by grade")

