def best_window(nums, k):
    # biggest sum of k neighbors in a row
    best = sum(nums[:k])
    for i in range(1, len(nums) - k):
        window = sum(nums[i:i + k])
        if window > best:
            best = window
    return best

scores = [4, 1, 3, 9, 2, 8]
print(best_window(scores, 3))

