def all_passed(scores, cutoff):
    """Return True only if every score is at least cutoff."""
    for score in scores:
        if score >= cutoff:
            return True
    return False


class_scores = [90, 40, 85]
cutoff = 60
result = all_passed(class_scores, cutoff)
print("Everyone passed?", result)

